#!/usr/bin/env bash
# Compare our codegen against purs's index.js for every module under
# sample-purs/output_ref. Strips the "// Generated by purs version ..." header
# and the "//# sourceMappingURL=" trailer from purs's output before comparing.
set -e

REF=/Users/avinashverma/purescriptCodeGen/sample-purs/output_ref
PROJECT=/Users/avinashverma/purescriptCodeGen
OUT=/tmp/pursjs-diff

if [ ! -d "$REF" ]; then
  echo "No reference output at $REF" >&2
  exit 1
fi

cd "$PROJECT"
spago build >/dev/null 2>&1 || { echo "spago build failed"; spago build; exit 1; }

mkdir -p "$OUT"

ok=0
diff=0
fail=0
failed=()
differed=()

# We invoke our compiled codegen directly via node so spago overhead is paid once.
run_codegen() {
  local corefn="$1"
  node --input-type=module -e "
import { main } from './output/PursJS.Main/index.js';
process.argv = [process.argv[0], 'main', '$corefn'];
main();
" 2>/dev/null
}

# Pre-warm node module cache once
run_codegen "$(find $REF -name corefn.json | head -1)" >/dev/null 2>&1 || true

modules=()
while IFS= read -r f; do modules+=("$f"); done < <(find "$REF" -name corefn.json | sort)

total=${#modules[@]}
echo "Comparing $total modules..."

for corefn in "${modules[@]}"; do
  moddir=$(dirname "$corefn")
  mod=$(basename "$moddir")
  ref_js="$moddir/index.js"
  [ -f "$ref_js" ] || continue

  ours=$(run_codegen "$corefn" 2>/dev/null) || { failed+=("$mod"); fail=$((fail+1)); continue; }

  ref_stripped=$(grep -v -E '^(// Generated by|//# sourceMappingURL=)' "$ref_js")
  ours_stripped=$(echo "$ours" | grep -v -E '^(// Generated by|//# sourceMappingURL=)')

  if [ "$ours_stripped" = "$ref_stripped" ]; then
    ok=$((ok+1))
    [ "${VERBOSE:-0}" = "1" ] && echo "OK   $mod"
  else
    differed+=("$mod")
    diff=$((diff+1))
    [ "${VERBOSE:-0}" = "1" ] && echo "DIFF $mod"
    # Save diff to inspect
    printf "%s\n" "$ref_stripped" > "$OUT/$mod.ref.js"
    printf "%s\n" "$ours_stripped" > "$OUT/$mod.ours.js"
  fi
done

echo ""
echo "Summary: $ok identical, $diff differ, $fail errored"
if [ ${#differed[@]} -gt 0 ] && [ "${VERBOSE:-0}" = "1" ]; then
  echo ""
  echo "Differences saved under $OUT/<mod>.{ref,ours}.js"
  for m in "${differed[@]:0:10}"; do
    echo ""
    echo "=== $m ==="
    diff -u "$OUT/$m.ref.js" "$OUT/$m.ours.js" | head -40 || true
  done
fi
